<script setup>
import {computed,ref,watch} from 'vue';
import RangeSlider from './RangeSlider.vue';
import FormField from './FormField.vue';import {t} from '../i18n';import {normalize} from '../state';
const props=defineProps({background:{type:Object,required:true},excluded:{type:Array,required:true},palette:Object,}),emit=defineEmits(['update:background','update:excluded']);
const search=ref(''),selected=ref('');
const identity=color=>[color?.brand??props.palette?.brand,color?.range,color?.code,color?.name].filter(Boolean).join(' · ');
const matches=computed(()=>props.palette?.colors.map((color,index)=>({color,index})).filter(row=>normalize(identity(row.color)).includes(normalize(search.value)))??[]);
const choices=computed(()=>{const rows=matches.value.slice(0,100),index=Number(selected.value);if(selected.value!==''&&!rows.some(row=>row.index===index)&&props.palette?.colors[index])rows.unshift({index,color:props.palette.colors[index]});return rows;});
const alreadyChosen=computed(()=>selected.value===''||props.excluded.includes(Number(selected.value)));
watch(()=>props.palette,()=>selected.value='');
function setBackground(key,value){emit('update:background',{...props.background,[key]:value});}
function add(kind){if(alreadyChosen.value)return;emit(`update:${kind}`,[...props[kind],Number(selected.value)]);}
</script>
<template>
 <div class="form-section"><div class="form-grid"><FormField :label="t('generationBackground')" v-slot="{id}"><select :id="id" :value="background.mode" @change="setBackground('mode',$event.target.value)"><option value="white">{{t('generationBackgroundWhite')}}</option><option value="remove">{{t('generationBackgroundRemove')}}</option><option value="color">{{t('generationBackgroundColor')}}</option><optgroup :label="t('generationAdvancedAlpha')"><option value="transparent">{{t('generationBackgroundTransparent')}}</option></optgroup></select></FormField><FormField v-if="['color','remove'].includes(background.mode)" :label="t('generationBackgroundColour')" v-slot="{id}"><input :id="id" type="color" :value="background.color" @input="setBackground('color',$event.target.value)"/></FormField><FormField v-if="background.mode==='remove'" :label="t('generationRemovalTolerance')" :help="t('generationRemovalHelp')" v-slot="{id,describedby}"><RangeSlider :id="id" :min="0" :max="80" :step="0.5" :model-value="background.tolerance" :aria-describedby="describedby" @update:model-value="setBackground('tolerance',$event)"/></FormField></div></div>
 <details v-if="palette" class="form-section"><summary>{{t('generationExcluded')}}</summary><p class="field-help">{{t('generationExcludeHelp')}}</p><div class="form-grid"><FormField :label="t('generationColourSearch')" v-slot="{id}"><input :id="id" v-model="search" type="search"/></FormField><FormField :label="t('generationColourChoice')" v-slot="{id}"><select :id="id" v-model="selected"><option value="">{{t('none')}}</option><option v-for="row in choices" :key="row.index" :value="String(row.index)">{{identity(row.color)}}</option></select></FormField></div><p v-if="matches.length>100" class="field-help">{{t('generationFirstMatches')}}</p><div class="actions"><button class="button small" :disabled="alreadyChosen||excluded.length>=palette.colors.length-1" @click="add('excluded')">{{t('generationExclude')}}</button></div><div><h3>{{t('generationExcluded')}} · {{excluded.length}}</h3><div v-for="index in excluded" :key="index" class="stat-row"><span>{{identity(palette.colors[index])}}</span><button class="button text small" :aria-label="`${t('remove')}: ${identity(palette.colors[index])}`" @click="emit('update:excluded',excluded.filter(value=>value!==index))">{{t('remove')}}</button></div></div></details>
</template>
